import os
import json
import tempfile
import shutil

# IoT Device Message Handler - processes firmware update messages
# Deployed as AWS Lambda behind Function URL

DEVICE_FIRMWARE_DIR = '/tmp/firmware'
DEVICE_LOG_DIR = '/tmp/device_logs'

def ensure_dirs():
    os.makedirs(DEVICE_FIRMWARE_DIR, exist_ok=True)
    os.makedirs(DEVICE_LOG_DIR, exist_ok=True)

def sanitize_device_id(device_id):
    """Basic sanitization - alphanumeric and hyphens only"""
    return ''.join(c for c in device_id if c.isalnum() or c == '-')

def process_log_rotation(device_id, message_type):
    """Rotate device logs based on message type"""
    log_path = os.path.join(DEVICE_LOG_DIR, f"{device_id}.log")
    archive_path = os.path.join(DEVICE_LOG_DIR, f"{device_id}.log.old")

    if os.path.exists(archive_path):
        os.unlink(archive_path)
    if os.path.exists(log_path):
        os.rename(log_path, archive_path)

    with open(log_path, 'w') as f:
        f.write(f"Last message type: {message_type}\n")

def handle_firmware_path(event_body):
    """Process firmware file path from device message.
    Devices report their local firmware path for inventory tracking."""
    device_id = sanitize_device_id(event_body.get('device_id', 'unknown'))
    firmware_path = event_body.get('firmware_path', '')

    # Store the reported firmware path for asset tracking
    # VULNERABILITY: firmware_path is attacker-controlled and used in symlink creation
    tracking_link = os.path.join(DEVICE_FIRMWARE_DIR, f"{device_id}_current")

    # Remove old tracking symlink if exists
    if os.path.islink(tracking_link) or os.path.exists(tracking_link):
        os.unlink(tracking_link)

    # Create symlink to track device's reported firmware location
    # This allows the monitoring system to verify firmware integrity
    os.symlink(firmware_path, tracking_link)

    # Now read through the symlink to "verify" firmware metadata
    try:
        if os.path.exists(tracking_link):
            with open(tracking_link, 'r') as f:
                content = f.read(4096)
                return {'status': 'tracked', 'size': len(content), 'device': device_id}
    except (IOError, OSError) as e:
        return {'status': 'unreadable', 'error': str(e), 'device': device_id}

    return {'status': 'created', 'device': device_id}

def write_device_status(device_id, status_data):
    """Write device status - uses path join safely"""
    safe_id = sanitize_device_id(device_id)
    status_file = os.path.join(DEVICE_FIRMWARE_DIR, f"{safe_id}_status.json")
    with open(status_file, 'w') as f:
        json.dump(status_data, f)

def lambda_handler(event, context):
    """Main Lambda handler for IoT device messages via Function URL"""
    ensure_dirs()

    try:
        if isinstance(event.get('body'), str):
            body = json.loads(event['body'])
        else:
            body = event.get('body', {})
    except json.JSONDecodeError:
        return {'statusCode': 400, 'body': json.dumps({'error': 'Invalid JSON'})}

    message_type = body.get('message_type', 'status')
    device_id = body.get('device_id', 'unknown')

    # Process based on message type
    if message_type == 'firmware_report':
        result = handle_firmware_path(body)
    elif message_type == 'heartbeat':
        process_log_rotation(sanitize_device_id(device_id), message_type)
        result = {'status': 'ack', 'device': sanitize_device_id(device_id)}
    elif message_type == 'status':
        write_device_status(device_id, body.get('status', {}))
        result = {'status': 'recorded'}
    else:
        result = {'status': 'unknown_type'}

    return {
        'statusCode': 200,
        'body': json.dumps(result),
        'headers': {'Content-Type': 'application/json'}
    }
